"""Shared selection logic: dedupe listings, convert to UTC, filter."""
import datetime as dt
import glob
import json
import os

START = dt.datetime(2025, 3, 1, tzinfo=dt.timezone.utc)   # inclusive
END = dt.datetime(2025, 6, 1, tzinfo=dt.timezone.utc)     # exclusive (end of 31 May UTC)


def load_listings(pass_dir):
    files = sorted(glob.glob(os.path.join(pass_dir, "page_*.json")))
    pages = [json.load(open(f)) for f in files]
    pages.sort(key=lambda p: p["page"])
    assert [p["page"] for p in pages] == list(range(1, pages[0]["total_pages"] + 1)), "missing pages"
    return [it for p in pages for it in p["items"]]


def dedupe(listings):
    """Keep first listing of each id; return (orders, duplicates_skipped)."""
    seen = {}
    skipped = 0
    for it in listings:
        if it["id"] in seen:
            if seen[it["id"]] != it:
                raise ValueError(f"conflicting duplicate for {it['id']}: {seen[it['id']]} vs {it}")
            skipped += 1
            continue
        seen[it["id"]] = it
    return list(seen.values()), skipped


def placed_utc(ts):
    t = dt.datetime.fromisoformat(ts)
    if t.tzinfo is None:
        raise ValueError(f"timestamp without offset: {ts}")
    return t.astimezone(dt.timezone.utc)


def qualifying(orders):
    return [o for o in orders
            if o["status"] == "shipped" and START <= placed_utc(o["placed_at"]) < END]

